-- M13 RPC security hardening
create or replace function public.submit_license_request(p_product_id uuid,p_intended_use text,p_requested_term text default '12_months',p_club_id uuid default null,p_requested_scope jsonb default '{}'::jsonb) returns uuid language plpgsql security invoker set search_path=public,private as $$ declare v_id uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if nullif(trim(p_intended_use),'') is null then raise exception 'Intended use is required'; end if; if not exists(select 1 from public.wfm_license_products where id=p_product_id and active=true) then raise exception 'License product is unavailable'; end if; if p_club_id is not null and not private.is_club_member(p_club_id) then raise exception 'Not authorized for this club'; end if; insert into public.wfm_license_requests(product_id,requested_by,club_id,requested_term,intended_use,requested_scope) values(p_product_id,auth.uid(),p_club_id,coalesce(nullif(trim(p_requested_term),''),'12_months'),trim(p_intended_use),coalesce(p_requested_scope,'{}'::jsonb)) returning id into v_id; return v_id; end; $$;
create or replace function public.review_license_request(p_request_id uuid,p_action text,p_admin_notes text default null) returns void language plpgsql security invoker set search_path=public,private as $$ begin if not private.is_wfm_admin() then raise exception 'WFM admin access required'; end if; if p_action not in ('under_review','approved','rejected','withdrawn') then raise exception 'Invalid review action'; end if; update public.wfm_license_requests set status=p_action,admin_notes=coalesce(p_admin_notes,admin_notes),reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=p_request_id; if not found then raise exception 'License request not found'; end if; end; $$;
create or replace function public.create_license_agreement(p_request_id uuid,p_agreement_reference text,p_starts_at timestamptz,p_ends_at timestamptz,p_permitted_scope jsonb default '{}'::jsonb,p_restrictions jsonb default '{}'::jsonb,p_commercial_terms jsonb default '{}'::jsonb,p_document_url text default null) returns uuid language plpgsql security invoker set search_path=public,private as $$ declare r public.wfm_license_requests; v_id uuid; v_plan text; begin if not private.is_wfm_admin() then raise exception 'WFM admin access required'; end if; select * into r from public.wfm_license_requests where id=p_request_id; if not found then raise exception 'License request not found'; end if; if r.status <> 'approved' then raise exception 'Request must be approved first'; end if; if nullif(trim(p_agreement_reference),'') is null then raise exception 'Agreement reference is required'; end if; if p_ends_at is not null and p_ends_at <= p_starts_at then raise exception 'Agreement end must follow start'; end if; insert into public.wfm_license_agreements(request_id,product_id,licensee_user_id,licensee_club_id,agreement_reference,status,starts_at,ends_at,permitted_scope,restrictions,commercial_terms,document_url,signed_at,created_by) values(r.id,r.product_id,r.requested_by,r.club_id,trim(p_agreement_reference),'active',p_starts_at,p_ends_at,coalesce(p_permitted_scope,r.requested_scope),coalesce(p_restrictions,'{}'::jsonb),coalesce(p_commercial_terms,'{}'::jsonb),p_document_url,now(),auth.uid()) returning id into v_id; select case when lp.code='data_license' then 'data_license' when lp.code='scouting' then 'professional' else 'club' end into v_plan from public.wfm_license_products lp where lp.id=r.product_id; insert into public.wfm_account_entitlements(user_id,club_id,plan_code,status,starts_at,ends_at,source,external_reference) values(r.requested_by,r.club_id,v_plan,'active',p_starts_at,p_ends_at,'license',p_agreement_reference); return v_id; end; $$;
